var n=`0787-mine-frit`;var t=`world-0787`;var o=`MU`;var s=`eastern-africa`;var a=4;var r=38;var g={en:`Mine Frit`,ua:`Смажена локшина мін фріт`};var l={en:`Mine Frit is a Mauritius classic prepared with egg noodles, yellow onion, carrot, white cabbage. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Смажена локшина мін фріт, страва кухні країни Маврикій зі складниками: яєчна локшина, жовта цибуля, морква, білоголова капуста. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var d=[{en:`Cook the listed ingredients in simmering water for about 8 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 8 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:8,i:[[`egg-noodles`,440,`g`],[`water`,1100,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,170,`g`],[`carrot`,200,`g`],[`white-cabbage`,210,`g`],[`sunflower-oil`,40,`ml`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 12 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 12 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:12,i:[[`chicken-thigh`,470,`g`],[`shrimp`,250,`g`],[`light-soy-sauce`,55,`ml`]]},{en:`Toss drained noodles with cooked protein, soy sauce and vegetables in a hot pan; keep ingredients moving and serve promptly.`,ua:`У гарячій сковороді змішайте обсушену локшину з готовим м’ясом, соєвим соусом та овочами; постійно рухайте складники й подавайте одразу.`,t:[`mixing`],m:5,i:[[`sesame-oil`,20,`ml`],[`green-onion`,80,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,16,`g`]]}];var u={slug:n,id:t,country:`MU`,region:s,servings:4,minutes:38,title:g,text:l,steps:d};export{o as country,u as default,t as id,r as minutes,s as region,a as servings,n as slug,d as steps,l as text,g as title};